class Solution {
public:
    int secondLargestElement(vector<int>& nums) {
        int large = INT_MIN;
        int secLarge= INT_MIN;
        for(int i=0;i<nums.size();i++){
            if(nums[i]>large){
                secLarge=large;
                large=nums[i];
            }else if(nums[i]>secLarge && nums[i]<large){
                secLarge=nums[i];
            }
        }
        return (secLarge==INT_MIN)?-1:secLarge;      
    }
};
```

## Complexity
